def check_password() -> bool:
    def _password_entered():
        correct = st.secrets.get("APP_PASSWORD", None)
        if correct is None:
            st.session_state["password_ok"] = True  # 沒設密碼時，本機測試放行
            return
        st.session_state["password_ok"] = (
            st.session_state.get("password_input", "") == correct
        )

    if st.session_state.get("password_ok"):
        return True

    st.title("零件耗用 / 故障率查詢")
    st.text_input("請輸入密碼", type="password", key="password_input",
                   on_change=_password_entered)
    if st.session_state.get("password_ok") is False:
        st.error("密碼錯誤，請再試一次")
    return False


# ---------------------------------------------------------------------------
# 資料讀取與清理
# ---------------------------------------------------------------------------
def read_excel(uploaded_file) -> pd.DataFrame:
    return pd.read_excel(uploaded_file)


def read_any_excel(file_bytes: bytes) -> pd.DataFrame:
    """同時支援 .xlsx（openpyxl）與舊版 .xls（xlrd）。"""
    return pd.read_excel(io.BytesIO(file_bytes))


def validate_columns(df: pd.DataFrame, required: list, label: str) -> list:
    missing = [c for c in required if c not in df.columns]
    if missing:
        st.error(
            f"「{label}」缺少欄位：{missing}。目前偵測到的欄位是：{list(df.columns)}。"
            f"請確認檔案格式，或告訴我正確欄位名稱讓我調整程式。"
        )
    return missing


def branch_from_repair_no(repair_no: str) -> str:
    if not isinstance(repair_no, str) or len(repair_no) < 5:
        return "未知"
    code = repair_no[4]  # 第5碼，index 4
    return BRANCH_CODE_MAP.get(code.upper(), "未知")


def extract_year_month(d) -> str:
    """回傳 'YYYY-MM'；輸入可能已經是 datetime，也可能是文字。"""
    if pd.isna(d):
        return None
    if isinstance(d, (pd.Timestamp, datetime, date)):
        return f"{d.year:04d}-{d.month:02d}"
    s = str(d)
    m = re.match(r"(\d{4})[-/](\d{1,2})", s)
    if m:
        return f"{int(m.group(1)):04d}-{int(m.group(2)):02d}"
    return None


def classify_part(code: str, name: str):
    """四層判定故障部位分類，回傳 (分類, 判定方式)：
    0. 人工修正清單（NAME_OVERRIDES）優先權最高
    1. 零件編號精確比對內嵌分類表
    2. 品名精確比對
    3. 品名包含某個分類名稱（關鍵字比對）
    4. 都對不到 -> 歸類「其他」，判定方式標「無法判別」讓使用者可以抽查"""
    code = str(code)
    name = str(name) if pd.notna(name) else ""
    if name in NAME_OVERRIDES:
        return NAME_OVERRIDES[name], "人工修正"
    if code in CODE_TO_CATEGORY:
        return CODE_TO_CATEGORY[code], "零件編號精確比對"
    if name in NAME_TO_CATEGORY:
        return NAME_TO_CATEGORY[name], "品名精確比對"
    for cat in KNOWN_CATEGORIES:
        if cat and cat in name:
            return cat, "關鍵字比對"
    return "其他", "無法判別"


@st.cache_data(show_spinner=False)
def build_usage_df(usage_files_bytes: list):
    """usage_files_bytes：一個或多個零件耗用資料檔案（bytes 的 list），
    直接全部合併，不需要去重（同一張維修單合法地用到同一個零件兩次的情況
    是存在的，用維修單號+零件編號去重會誤刪真實資料）。
    機型分類、故障部位分類都改用內嵌對照表，不再需要另外上傳檔案。"""
    # 2026/08 新增：不同批次的耗用資料，「有償/無償」這欄的名稱可能會有些微
    # 差異（例如「有償_無償」），這裡列出已知的別名，讀檔時自動對應成標準
    # 欄名，不用每次都因為欄位名稱一點點不一樣就整份檔案被拒收。
    COLUMN_ALIASES = {
        "有償_無償": "有償/無償",
    }
    dfs = []
    for i, b in enumerate(usage_files_bytes, start=1):
        df = read_any_excel(b)
        df = df.rename(columns={k: v for k, v in COLUMN_ALIASES.items() if k in df.columns})
        validate_columns(df, list(ASSUMED_USAGE_COLUMNS.values()), f"零件耗用資料（第{i}個檔案）")
        dfs.append(df)
    usage = pd.concat(dfs, ignore_index=True)

    model_map = pd.DataFrame(MODEL_RECORDS)  # 欄位: 機型/類別/內外機

    cols = ASSUMED_USAGE_COLUMNS

    # 排除零件編號空白、數量為0的列（不是真的耗用，是同一張維修單的參考列）
    usage = usage[usage[cols["part_no"]].notna() & (usage[cols["qty"]] > 0)].copy()

    usage["年月"] = usage[cols["fault_date"]].apply(extract_year_month)
    usage["維修分公司"] = usage[cols["repair_no"]].apply(branch_from_repair_no)
    usage["有無償"] = usage[cols["payment_type"]]

    # 2026/08 新增：縣市別、故障碼（來源欄位選填，舊版檔案沒有這兩欄時退回預設值）
    if COUNTY_SRC_COL in usage.columns:
        raw_county = usage[COUNTY_SRC_COL].fillna("").astype(str).str.strip()
        raw_county = raw_county.replace(COUNTY_ALIASES)
        usage["縣市別"] = raw_county.where(raw_county.isin(COUNTY_ORDER), UNKNOWN_COUNTY)
    else:
        usage["縣市別"] = UNKNOWN_COUNTY

    if FAULT_CODE_SRC_COL in usage.columns:
        usage["故障碼"] = (
            usage[FAULT_CODE_SRC_COL].fillna("").astype(str)
            .str.replace(" ", "", regex=False).str.strip()
        )
        usage.loc[usage["故障碼"].isin(["", "nan"]), "故障碼"] = "未知"
    else:
        usage["故障碼"] = "未知"

    # 關聯機型分類表 -> 類別 / 內外機
    # 2026/08 修bug：耗用資料的機型欄位常有前後空白（例如 " FTX25GVLT "），
    # 沒清掉會導致明明兩邊都有登記，卻對不到分類、被誤判成「未分類機型」。
    usage[cols["model"]] = usage[cols["model"]].astype(str).str.strip()
    model_map["機型"] = model_map["機型"].astype(str).str.strip()
    model_lookup = model_map.set_index("機型")[["類別", "內外機"]]
    usage = usage.join(model_lookup, on=cols["model"])
    usage = usage.rename(columns={cols["model"]: "機型"})

    # ⚠️ 2026/08 重要修正：以前這裡如果機型分類表沒有這個機型（join失敗，
    # 類別/內外機變成 NaN），後面 groupby 會直接把這些列「整組排除」，
    # 數字悄悄變少但畫面上完全看不出來。改成用「未分類機型」頂著，這樣
    # 這些機型還是會出現在結果裡（歸在「未分類機型」類別下），不會憑空消失，
    # 同時上面也會跳警告列出哪些機型沒有分類資料。
    unmatched_models = sorted(
        usage.loc[usage["類別"].isna(), "機型"].dropna().unique().tolist()
    )
    usage["類別"] = usage["類別"].fillna("未分類機型")
    usage["內外機"] = usage["內外機"].fillna("未分類機型")

    # 故障部位：四層判定（人工修正 -> 零件編號 -> 品名精確 -> 品名關鍵字 -> 其他）
    classified = usage.apply(
        lambda r: classify_part(r[cols["part_no"]], r[cols["part_name"]]),
        axis=1, result_type="expand",
    )
    usage["故障部位"] = classified[0]
    usage["判定方式"] = classified[1]
    usage = usage.rename(columns={cols["part_no"]: "零件料號"})
    usage["零件料號"] = usage["零件料號"].astype(str)

    # 分類判定結果稽核清單（給使用者抽查用，尤其是「無法判別」的）
    audit = (
        usage[["零件料號", cols["part_name"], "故障部位", "判定方式"]]
        .drop_duplicates()
        .rename(columns={cols["part_name"]: "品名"})
        .sort_values(["判定方式", "零件料號"])
        .reset_index(drop=True)
    )

    return usage, audit, model_map, unmatched_models


@st.cache_data(show_spinner=False)
def build_shipment_df(shipment_bytes):
    xl = pd.ExcelFile(io.BytesIO(shipment_bytes))
    chosen = None
    for name in xl.sheet_names:
        tmp = xl.parse(name, nrows=3)
        if SHIPMENT_MODEL_COL in tmp.columns and any(
            SHIPMENT_YEAR_COL_PATTERN.match(str(c)) for c in tmp.columns
        ):
            chosen = name
            break
    if chosen is None:
        chosen = xl.sheet_names[0]
    df = xl.parse(chosen)
    validate_columns(df, [SHIPMENT_MODEL_COL], "出貨資料")
    year_cols = [c for c in df.columns if SHIPMENT_YEAR_COL_PATTERN.match(str(c))]
    if not year_cols:
        st.warning("在出貨資料裡找不到「20XX販售量」這種格式的欄位，累積出貨量會算不出來，"
                   "請確認出貨資料的欄位名稱。")
    return df, year_cols


