MASS_RETAILERS = {
    "網路家庭國際資訊", "富邦媒體", "特力屋", "全國電子", "集雅社", "家福", "遠百",
    "燦坤", "好市多物流", "大潤發", "神腦", "金門電器音響", "好市多中和", "好市多汐止",
    "好市多台中", "好市多新竹", "好市多新莊", "好市多內湖", "東森得易購", "倍適得",
    "香港商雅虎資訊", "好市多中壢", "元暉",
}
