COUNTY_SRC_COL = "縣市別"
FAULT_CODE_SRC_COL = "故障代碼"

# 2026/08 新增：使用者指定的22縣市＋連江縣＝23個標準縣市，依「直轄市/縣/市」
# 分組排序（不是字母排序）。資料裡不在這份清單、也不是下面別名清單裡的值，
# 一律歸類成「資料不明」，不會憑空消失，也不會讓髒資料混進正式縣市選項。
COUNTY_ORDER = [
    "臺北市", "新北市", "桃園市", "臺中市", "臺南市", "高雄市",
    "宜蘭縣", "新竹縣", "苗栗縣", "彰化縣", "南投縣", "雲林縣", "嘉義縣",
    "屏東縣", "臺東縣", "花蓮縣", "澎湖縣", "金門縣", "連江縣",
    "基隆市", "新竹市", "嘉義市",
]
# 「台」「臺」是同一個字的異體字，資料裡常混用；「桃園縣」是「桃園市」
# 2014年改制前的舊名，一併視為同一個縣市，不會被誤判成「資料不明」。
COUNTY_ALIASES = {
    "台北市": "臺北市", "台中市": "臺中市", "台南市": "臺南市", "台東縣": "臺東縣",
    "桃園縣": "桃園市",
}


def normalize_county(raw_series: pd.Series) -> pd.Series:
    """把任意一欄原始縣市/地址字串，正規化成標準23縣市之一，或「資料不明」。
    共用給零件耗用資料的縣市別欄位、報修案件資料的地址欄位（取前3碼）用。"""
    s = raw_series.fillna("").astype(str).str.strip().replace(COUNTY_ALIASES)
    return s.where(s.isin(COUNTY_ORDER), UNKNOWN_COUNTY)


def _apply_filter(scope, col, selected):
    """selected 是 multiselect 回傳的 list；空 list 代表不篩選（=全部）。"""
    if selected:
        scope = scope[scope[col].isin(selected)]
    return scope


def usage_table(usage_df, start_ym, end_ym, f_cat, f_io, f_model, f_part, f_faultcode,
                 f_partno, f_branch, f_payment, f_county):
    """查找年月(起始~結束) 整段期間內的耗用量加總。
    2026/08 更新：類別/機型/故障部位/故障碼/零件料號/維修分公司/有無償/縣市別
    都改成多選（list，空 list = 不篩選），加了「當期耗用金額」欄位，最後加
    一列總計。「機型/故障部位/故障碼/零件料號/維修分公司別/縣市別」都支援
    「所有XXX」選項：選了就不篩選、也不分組，結果直接彙總，避免欄數/列數
    太多（「有無償」本來就只是篩選條件、不是分組欄位，所以「所有有無償」
    只需要跳過篩選，不需要額外處理分組）。"""
    scope = usage_df[(usage_df["年月"] >= start_ym) & (usage_df["年月"] <= end_ym)]
    scope = _apply_filter(scope, "類別", f_cat)
    if f_io != "全部": scope = scope[scope["內外機"] == f_io]

    all_models_mode = ALL_MODELS_OPTION in f_model
    all_parts_mode = ALL_FAULTPARTS_OPTION in f_part
    all_faultcode_mode = ALL_FAULTCODE_OPTION in f_faultcode
    all_partno_mode = ALL_PARTNO_OPTION in f_partno
    all_branches_mode = ALL_BRANCHES_OPTION in f_branch
    all_counties_mode = ALL_COUNTIES_OPTION in f_county
    all_payment_mode = ALL_PAYMENT_OPTION in f_payment

    if not all_models_mode: scope = _apply_filter(scope, "機型", f_model)
    if not all_parts_mode: scope = _apply_filter(scope, "故障部位", f_part)
    if not all_faultcode_mode: scope = _apply_filter(scope, "故障碼", f_faultcode)
    if not all_partno_mode: scope = _apply_filter(scope, "零件料號", f_partno)
    if not all_branches_mode: scope = _apply_filter(scope, "維修分公司", f_branch)
    if not all_payment_mode: scope = _apply_filter(scope, "有無償", f_payment)
    if not all_counties_mode: scope = _apply_filter(scope, "縣市別", f_county)

    group_cols = ["類別", "內外機"] + \
        ([] if all_models_mode else ["機型"]) + \
        ([] if all_parts_mode else ["故障部位"]) + \
        ([] if all_faultcode_mode else ["故障碼"]) + \
        ([] if all_partno_mode else ["零件料號"]) + \
        ([] if all_branches_mode else ["維修分公司"]) + \
        ([] if all_counties_mode else ["縣市別"])
    qty_col = ASSUMED_USAGE_COLUMNS["qty"]
    amt_col = ASSUMED_USAGE_COLUMNS["subtotal"]
    result = (
        scope.groupby(group_cols, as_index=False)[[qty_col, amt_col]]
        .sum()
        .rename(columns={"內外機": "室內/外機", qty_col: "當期耗用量", amt_col: "當期耗用金額"})
    )
    if all_models_mode:
        result["機型"] = ALL_MODELS_OPTION
    if all_parts_mode:
        result["故障部位"] = ALL_FAULTPARTS_OPTION
    if all_faultcode_mode:
        result["故障碼"] = ALL_FAULTCODE_OPTION
    if all_partno_mode:
        result["零件料號"] = ALL_PARTNO_OPTION
    if all_branches_mode:
        result["維修分公司"] = ALL_BRANCHES_OPTION
    if all_counties_mode:
        result["縣市別"] = ALL_COUNTIES_OPTION
    result = result[USAGE_TABLE_COLS]

    if len(result) > 0:
        total_row = {c: "" for c in USAGE_TABLE_COLS}
        total_row["類別"] = "總計"
        total_row["當期耗用量"] = result["當期耗用量"].sum()
        total_row["當期耗用金額"] = result["當期耗用金額"].sum()
        result = pd.concat([result, pd.DataFrame([total_row])], ignore_index=True)

    return result, scope


# ---------------------------------------------------------------------------
# 業務邏輯：故障率
# ---------------------------------------------------------------------------
def cumulative_shipment(shipment_df, year_cols, model, end_ym):
    """<最早年度>/01/01 ~ end_ym 月底 的累積出貨量（受限於出貨資料是年度粒度）"""
    end_year = int(end_ym.split("-")[0])
    row = shipment_df[shipment_df[SHIPMENT_MODEL_COL] == model]
    if row.empty:
        return 0
    total = 0
    for c in year_cols:
        y = int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1))
        if y <= end_year:
            total += row[c].sum()
    return total


def earliest_shipment_year(year_cols) -> int:
    years = [int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)) for c in year_cols]
    return min(years) if years else None


def earliest_nonzero_year_for_model(shipment_df, year_cols, model) -> int:
    """2026/08 新增：不是抓檔案裡最早的年度欄位，而是抓「這個機型」出貨量
    第一次不為 0 的那一年（例如檔案從2010年開始有欄位，但這台機型是2016年
    才開始賣，就回傳2016）。找不到機型或全部是0，退回檔案最早年度。"""
    row = shipment_df[shipment_df[SHIPMENT_MODEL_COL] == model]
    if row.empty:
        return earliest_shipment_year(year_cols)
    years_sorted = sorted(
        (int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)), c) for c in year_cols
    )
    for y, c in years_sorted:
        if row[c].sum() > 0:
            return y
    return earliest_shipment_year(year_cols)


def build_year_options(shipment_df, year_cols, usage_df):
    """2026/08 新增：歷年累積故障率的「查找年月」改成年度下拉選單，不能選
    月/日。過去年度顯示「YYYY」，代表算到該年12月底；今年這種還沒過完的
    年度，顯示「YYYY/MM」（MM=今天往前推一個月，也就是最後一個完整月），
    以後每年會依系統當天日期自動這樣算，不用每年手動改。
    回傳 [(顯示文字, 對應的end_ym), ...]，由舊到新排序。"""
    years = {int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)) for c in year_cols}
    usage_years = {int(ym.split("-")[0]) for ym in usage_df["年月"].dropna()}
    all_years = sorted(years | usage_years)
    if not all_years:
        return []

    today = datetime.now()
    current_year = today.year
    options = []
    for y in all_years:
        if y > current_year:
            continue
        if y == current_year:
            if today.month == 1:
                continue  # 今年還沒有任何一個完整月份，先不提供這個選項
            last_complete_month = today.month - 1
            options.append((f"{y}/{last_complete_month:02d}", f"{y}-{last_complete_month:02d}"))
        else:
            options.append((str(y), f"{y}-12"))
    return options


def _filter_scope(usage_df, f_cat, f_io, f_model, f_part, f_partno, f_branch):
    scope = usage_df
    scope = _apply_filter(scope, "類別", f_cat)
    if f_io != "全部": scope = scope[scope["內外機"] == f_io]
    if ALL_MODELS_OPTION not in f_model:
        scope = _apply_filter(scope, "機型", f_model)
    if ALL_FAULTPARTS_OPTION not in f_part:
        scope = _apply_filter(scope, "故障部位", f_part)
    if ALL_PARTNO_OPTION not in f_partno:
        scope = _apply_filter(scope, "零件料號", f_partno)
    if ALL_BRANCHES_OPTION not in f_branch:
        scope = _apply_filter(scope, "維修分公司", f_branch)
    return scope


def rate_table(usage_df, shipment_df, year_cols, end_ym,
                f_cat, f_io, f_model, f_part, f_partno, f_branch):
    """2026/08 大改：
    - 類別/機型/故障部位/零件料號/維修分公司 都改成多選，且都支援「所有XXX」
      收合選項（選了就不分那個欄位分組，結果列數變少）
    - 新增「去年累積故障率」「前年累積故障率」兩欄（同一組合，基準年往前推
      1年/2年，一律算到該年12月底）
    - 總計列、以及「所有機型」收合後的列，故障率都是用「這個組合底下實際
      涵蓋到的機型」各自的累積出貨量加總當分母，每個機型只算一次，不會因為
      同一機型出現在多列（不同故障部位/零件料號）而被重複加總出貨量
    - 回傳 (result_df, red_flags)：red_flags 是跟 result_df 同樣長度的
      bool list，True 代表「該月故障率」比「去年累積故障率」成長超過3成，
      畫面上要整列反紅
    算法：累積耗用數量 ÷ 累積出貨量，都是（該機型最早非0年度）/01/01 ~
    基準月底。當一列涵蓋多個機型時，各自機型用各自的最早年度計算，互不影響。"""
    scope = _filter_scope(usage_df, f_cat, f_io, f_model, f_part, f_partno, f_branch)

    all_models_mode = ALL_MODELS_OPTION in f_model
    all_parts_mode = ALL_FAULTPARTS_OPTION in f_part
    all_partno_mode = ALL_PARTNO_OPTION in f_partno
    all_branches_mode = ALL_BRANCHES_OPTION in f_branch

    # 先在「完整細節」(含機型) 的粒度算好每個組合的耗用數量與該機型的出貨量，
    # 之後再依使用者實際想看的欄位重新彙總，這樣才能保證同一機型的出貨量
    # 不會因為被拆到多列（不同故障部位/零件料號）而重複計入。
    full_group_cols = ["類別", "內外機", "機型", "故障部位", "零件料號", "維修分公司"]
    combos = scope[full_group_cols].drop_duplicates()

    if combos.empty:
        return pd.DataFrame(columns=RATE_TABLE_COLS), []

    end_year = int(end_ym.split("-")[0])
    last_year_end = f"{end_year - 1}-12"
    two_years_ago_end = f"{end_year - 2}-12"

    def cumulative_qty_by_combo(target_ym):
        sub = scope[scope["年月"] <= target_ym]
        if sub.empty:
            return pd.Series(dtype=float)
        return sub.groupby(full_group_cols)[ASSUMED_USAGE_COLUMNS["qty"]].sum()

    cum_end = cumulative_qty_by_combo(end_ym)
    cum_last_year = cumulative_qty_by_combo(last_year_end)
    cum_two_years_ago = cumulative_qty_by_combo(two_years_ago_end)

    combos = combos.set_index(full_group_cols)
    combos["_qty_end"] = cum_end.reindex(combos.index).fillna(0)
    combos["_qty_last_year"] = cum_last_year.reindex(combos.index).fillna(0)
    combos["_qty_two_years_ago"] = cum_two_years_ago.reindex(combos.index).fillna(0)
    combos = combos.reset_index()

    unique_models = combos["機型"].unique().tolist()
    ship_end = {m: cumulative_shipment(shipment_df, year_cols, m, end_ym) for m in unique_models}
    ship_last_year = {m: cumulative_shipment(shipment_df, year_cols, m, last_year_end) for m in unique_models}
    ship_two_years_ago = {m: cumulative_shipment(shipment_df, year_cols, m, two_years_ago_end) for m in unique_models}
    combos["_ship_end"] = combos["機型"].map(ship_end)
    combos["_ship_last_year"] = combos["機型"].map(ship_last_year)
    combos["_ship_two_years_ago"] = combos["機型"].map(ship_two_years_ago)

    # 使用者實際想看的分組欄位（拿掉選了「所有XXX」的那幾個維度）
    output_group_cols = ["類別", "內外機"] + \
        ([] if all_models_mode else ["機型"]) + \
        ([] if all_parts_mode else ["故障部位"]) + \
        ([] if all_partno_mode else ["零件料號"]) + \
        ([] if all_branches_mode else ["維修分公司"])

    # 2026/08 修bug：pandas 3.0 起，groupby().apply() 預設會把「拿去分組的
    # 欄位」從傳進 function 的資料裡拿掉，導致「機型」還是分組欄位時
    # sub["機型"] 直接 KeyError。改成不用 apply()：數量用一般的
    # groupby().sum()；出貨量分兩種情況處理——「機型」還是分組欄位時，
    # 每組本來就只對應一個機型，直接用該機型的值；「機型」被收合掉時，
    # 才需要额外算「這組裡有哪些不重複的機型」，把它們的出貨量加總一次
    # （不會因為同一機型出現在多列而重複計入）。
    qty_agg = (
        combos.groupby(output_group_cols, dropna=False)
        [["_qty_end", "_qty_last_year", "_qty_two_years_ago"]]
        .sum()
        .reset_index()
    )

    if "機型" in output_group_cols:
        qty_agg["_ship_end"] = qty_agg["機型"].map(ship_end)
        qty_agg["_ship_last_year"] = qty_agg["機型"].map(ship_last_year)
        qty_agg["_ship_two_years_ago"] = qty_agg["機型"].map(ship_two_years_ago)
    else:
        model_sets = combos.groupby(output_group_cols, dropna=False)["機型"].agg(
            lambda s: list(s.unique())
        )
        qty_agg = qty_agg.set_index(output_group_cols)
        qty_agg["_ship_end"] = model_sets.apply(lambda ms: sum(ship_end[m] for m in ms))
        qty_agg["_ship_last_year"] = model_sets.apply(lambda ms: sum(ship_last_year[m] for m in ms))
        qty_agg["_ship_two_years_ago"] = model_sets.apply(lambda ms: sum(ship_two_years_ago[m] for m in ms))
        qty_agg = qty_agg.reset_index()

    agg = qty_agg.rename(columns={"_qty_end": "累積故障數量"})

    def safe_rate(qty, ship):
        return (qty / ship) if ship else None

    agg["_rate_end"] = agg.apply(lambda r: safe_rate(r["累積故障數量"], r["_ship_end"]), axis=1)
    agg["_rate_last_year"] = agg.apply(lambda r: safe_rate(r["_qty_last_year"], r["_ship_last_year"]), axis=1)
    agg["_rate_two_years_ago"] = agg.apply(
        lambda r: safe_rate(r["_qty_two_years_ago"], r["_ship_two_years_ago"]), axis=1
    )

    # 異常反紅：該月故障率比去年累積故障率成長超過3成
    def is_anomaly(row):
        cur, prev = row["_rate_end"], row["_rate_last_year"]
        if pd.isna(cur) or pd.isna(prev) or prev <= 0:
            return False
        return (cur - prev) / prev > 0.3

    red_flags = agg.apply(is_anomaly, axis=1).tolist()

    agg = agg.rename(columns={
        "內外機": "室內/外機",
        "_rate_end": "該月/該料號累積故障率",
        "_rate_last_year": "去年累積故障率",
        "_rate_two_years_ago": "前年累積故障率",
    })
    for c in ["該月/該料號累積故障率", "去年累積故障率", "前年累積故障率"]:
        agg[c] = agg[c].apply(lambda v: f"{v:.2%}" if pd.notna(v) else "-")
    if all_models_mode:
        agg["機型"] = ALL_MODELS_OPTION
    if all_parts_mode:
        agg["故障部位"] = ALL_FAULTPARTS_OPTION
    if all_partno_mode:
        agg["零件料號"] = ALL_PARTNO_OPTION
    if all_branches_mode:
        agg["維修分公司"] = ALL_BRANCHES_OPTION
    result = agg[RATE_TABLE_COLS]

    if len(result) > 0:
        total_qty = result["累積故障數量"].sum()
        total_ship_end = sum(ship_end[m] for m in unique_models)
        total_ship_last_year = sum(ship_last_year[m] for m in unique_models)
        total_ship_two_years_ago = sum(ship_two_years_ago[m] for m in unique_models)
        total_row = {c: "" for c in RATE_TABLE_COLS}
        total_row["類別"] = "總計"
        total_row["累積故障數量"] = total_qty
        total_row["該月/該料號累積故障率"] = (
            f"{total_qty/total_ship_end:.2%}" if total_ship_end else "-"
        )
        total_qty_last_year = agg["_qty_last_year"].sum()
        total_row["去年累積故障率"] = (
            f"{total_qty_last_year/total_ship_last_year:.2%}" if total_ship_last_year else "-"
        )
        total_row["前年累積故障率"] = (
            f"{agg['_qty_two_years_ago'].sum()/total_ship_two_years_ago:.2%}" if total_ship_two_years_ago else "-"
        )
        result = pd.concat([result, pd.DataFrame([total_row])], ignore_index=True)
        red_flags = red_flags + [False]  # 總計列不參與反紅判斷

    return result, red_flags


